function setGameImage(img,name){
  const candidates=[`assets/${name}.webp`,`./assets/${name}.webp`,`/${name}.webp`,`${name}.webp`];
  let index=0;
  img.onerror=()=>{index++; if(index<candidates.length) img.src=candidates[index]; else {img.style.visibility='hidden'; img.parentElement?.classList.add('image-missing');}};
  img.src=candidates[0];
}

const faction=()=>F.find(f=>f.id===S.faction),prov=id=>S.provinces.find(p=>p.id===id),mine=()=>S.provinces.filter(p=>p.owner===S.faction),armyAt=id=>S.armies.find(a=>a.owner===S.faction&&a.loc===id),armiesAt=id=>S.armies.filter(a=>a.loc===id),fmt=n=>Number(n).toLocaleString('fr-FR');
function save(){localStorage.setItem('aoc-save-v4',JSON.stringify(S));$('saveState')?.textContent;}
function note(msg){S.log.unshift({turn:S.turn,msg});S.log=S.log.slice(0,100);renderLog();save();}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').classList.remove('show'),2300);}
function bootCards(){$('factions').innerHTML=F.map(f=>`<button class="faction" data-id="${f.id}"><span class="symbol">${f.symbol}</span><strong>${f.name}</strong><p>${f.desc}</p><small>Seigneur : ${f.leader}</small></button>`).join('');document.querySelectorAll('.faction').forEach(b=>b.onclick=()=>{document.querySelectorAll('.faction').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('begin').disabled=false;$('begin').dataset.id=b.dataset.id;});}
function begin(){let f=F.find(x=>x.id===$('begin').dataset.id);S={version:5,faction:f.id,difficulty:$('difficulty').value,turn:1,gold:f.gold,iron:f.iron,magic:f.magic,food:f.food,provinces:P.map(p=>({...p,settlements:(p.settlements||[]).map(c=>({...c,owner:p.owner})),buildings:[],owner:p.owner,level:1})),armies:[{id:'A1',owner:f.id,loc:f.capital,units:f.units.slice(0,2).map(u=>({name:u[0],count:u[1]})),moved:0},{id:'K1',owner:'chaos',loc:'norsca',units:[{name:'Maraudeurs',count:260},{name:'Guerriers du Chaos',count:90}],moved:0},{id:'V1',owner:'vampires',loc:'sylvania',units:[{name:'Squelettes',count:220},{name:'Gardes des cryptes',count:90}],moved:0},{id:'G1',owner:'greenskins',loc:'badlands',units:[{name:'Orques',count:260},{name:'Gobelins',count:180}],moved:0},{id:'D1',owner:'dwarfs',loc:'worldsedge',units:[{name:'Guerriers nains',count:220}],moved:0}],log:[],tech:[],relations:F.filter(x=>x.id!==f.id).map(x=>({id:x.id,relation:0,treaty:'Paix'})),lords:[{name:f.leader,level:1,xp:0,trait:'Chef de guerre',loyalty:100}],events:[]};prov(f.capital).owner=f.id;selected=f.capital;$('start').classList.add('hidden');$('game').classList.remove('hidden');note(`La bannière ${f.name} est levée. ${f.leader} prend le commandement depuis ${prov(f.capital).name}.`);render();}
function totalUnits(){return S.armies.filter(a=>a.owner===S.faction).reduce((n,a)=>n+a.units.reduce((m,u)=>m+u.count,0),0)}
function render(){if(!S)return;let f=faction(),inc=mine().reduce((n,p)=>n+p.income,0)+(S.tech.includes('Administration impériale')?mine().reduce((n,p)=>n+p.income,0)*.1:0);$('factionName').textContent=f.name;$('commanderName').textContent=f.leader;setGameImage($('commanderPortrait'),'karl-franz');$('armyCount').textContent=`${S.armies.length} armée(s) · ${mine().length} province(s)`;$('turn').textContent='TOUR '+S.turn;$('season').textContent=['PRINTEMPS','ÉTÉ','AUTOMNE','HIVER'][(S.turn-1)%4]+' · 2522 CI';$('gold').textContent=fmt(S.gold);$('income').textContent=`+${fmt(Math.round(inc))}/tour`;$('iron').textContent=fmt(S.iron);$('magic').textContent=fmt(S.magic);$('food').textContent=fmt(S.food);$('armyCount').title=`${totalUnits()} soldats`;renderMap();renderProvince();renderArmy();renderEvents();renderLog();if(tab!=='carte')renderTab(tab);save();}
